CREATE TABLE win14_regions (sale_id INTEGER PRIMARY KEY, region TEXT NOT NULL, salesperson TEXT NOT NULL, amount INTEGER NOT NULL);
INSERT INTO win14_regions VALUES (1, 'East', 'Asha', 100), (2, 'East', 'Bilal', 50), (3, 'West', 'Mira', 80), (4, 'West', 'Noor', 20);
SELECT salesperson, region, amount, SUM(amount) OVER (PARTITION BY region) AS region_total FROM win14_regions ORDER BY region, salesperson;

